<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Support\Facades\DB;
class EnsureAdminAuthenticated {
 public function handle($request,Closure $next){if(!$request->session()->has('admin_id'))return redirect()->route('admin.login')->with('exception','Please sign in to access the admin panel.');$admin=DB::table('tbl_admin as a')->leftJoin('admin_roles as r','r.id','=','a.role_id')->where('a.admin_id',$request->session()->get('admin_id'))->select('a.*','r.name as role_name','r.permissions')->first();if(!$admin||!$admin->is_active){$request->session()->forget(['admin_id','admin_name','admin_role','admin_permissions']);return redirect()->route('admin.login')->with('exception','This administrator account is disabled.');}$permissions=(array)json_decode($admin->permissions,true);$request->session()->put(['admin_role'=>$admin->role_name,'admin_permissions'=>$permissions]);$required=$this->permissionFor($request->path());if($required&&!in_array($required,$permissions,true))abort(403,'You do not have permission to access this administration area.');return $next($request);}
 private function permissionFor($path){if($path==='admin/logout')return null;if(preg_match('#^admin-data/(suppliers|locations)#i',$path))return 'inventory';if(preg_match('#^admin-data/#i',$path))return 'catalog';if(preg_match('#^(admin-users|admin-roles|admin-activity)#i',$path))return 'staff';if(preg_match('#^sales-reports#i',$path))return 'reports';if(preg_match('#^(manage-orders|delivery-zones|returns)#i',$path))return 'orders';if(preg_match('#^(inventory|purchasing|suppliers|purchase-orders|stock-locations|stock-transfers)#i',$path))return 'inventory';if(preg_match('#^(customer-inbox|review/|question/|support/|service-claims|stock-alerts)#i',$path))return 'customers';if(preg_match('#^(coupons|abandoned-carts|marketing-campaigns|customer-segments)#i',$path))return 'marketing';if(preg_match('#^(site-customization|site-settings|save-banner|toggle-banner|delete-banner|payment-methods|emi-plans|admin-notifications|system-health|system-monitor|integrations|api-clients|webhook-endpoints)#i',$path))return 'settings';if(preg_match('#^(add-|manage-category|manage-subCategory|manage-manufacturer|manage-product|save-|update-|published-|unpublished-|delete-category|delete-subCategory|delete-manufacturer|delete-product|edit-|catalog-attributes)#i',$path))return 'catalog';return 'dashboard';}
}
